    /**
     * Tests getting all Clinicians.
     *
     * @return    Collection
     */
    public List<Clinician> testGetAll() throws Throwable {
    LOGGER.info( "ClinicianTest:testGetAll() - Retrieving Collection of Clinicians:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Clinician : " );
    List<Clinician> collection  = null;

    try {
        // call the static get method on the ClinicianService
        collection = service.getAllClinician();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Clinician currEntity  = null;
            Iterator<Clinician> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getClinicianId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

